  1	/**
  2	 * GUI HTTP Server
  3	 *
  4	 * Standalone Node.js HTTP server that routes requests to API handlers
  5	 * (gui/api.ts) and serves static files from gui/public/. This is a SEPARATE
  6	 * process from the MCP server — stdout logging is allowed and expected.
  7	 *
  8	 * CLI Arguments:
  9	 *   --port <n>           Listen port (default: 3420)
 10	 *   --ledger-dir <path>  Ledger root path (handled by resolveLedgerRoot())
 11	 */
 12	
 13	import { createServer } from 'node:http';
 14	import type { IncomingMessage, ServerResponse } from 'node:http';
 15	import { readFile } from 'node:fs/promises';
 16	import { join, extname, dirname, resolve } from 'node:path';
 17	import { fileURLToPath } from 'node:url';
 18	
 19	import { resolveLedgerRoot, resolveProjectDir, ORCHESTRATOR_LOGS_DIR, WORKSPACE_ROOT } from '../src/utils/ledger-root.js';
 20	import { SAFE_SLUG_REGEX } from '../src/utils/constants.js';
 21	import { captureWorkspaceVersions } from '../src/utils/workspace-versions.js';
 22	import type { WorkspaceVersions } from '../src/utils/workspace-versions.js';
 23	import { readConfigFromDisk, startConfigWatcher } from '../src/gui/config.js';
 24	import { startAutoArchiveTimer } from '../src/gui/auto-archive.js';
 25	import {
 26	  handleListRunLogs,
 27	  handleGetRunLog,
 28	} from '../src/gui/handlers/run-log-handlers.js';
 29	import {
 30	  handleListProjects,
 31	  handleGetProject,
 32	  handleGetPlanDocument,
 33	  handleGetSynthesisDocument,
 34	  handleListWorkPackages,
 35	  handleGetWorkPackage,
 36	  handleDeleteProject,
 37	  handleGetInsights,
 38	  handleGetConfig,
 39	  handleUpdateConfig,
 40	  handleResetProject,
 41	  handleGetProjectHealth,
 42	  handleGetWorkPackageOverview,
 43	  handleRenameProject,
 44	  handleArchiveProject,
 45	  handleUnarchiveProject,
 46	  handleMarkProjectComplete,
 47	  handleListDialogues,
 48	  handleGetDialogueFile,
 49	  handleListChunks,
 50	  handleGetChunkFile,
 51	  handleOrchestratorStart,
 52	  handleGetOrchestratorQueue,
 53	  handleOrchestratorKill,
 54	  handleOrchestratorDismiss,
 55	  handleGetRunStatus,
 56	  ApiError,
 57	} from './api.js';
 58	import {
 59	  handleListKnowledge,
 60	  handleUpdateKnowledge,
 61	  handleDeleteKnowledge,
 62	  handlePromoteKnowledge,
 63	  handleMoveKnowledge,
 64	} from './api-knowledge.js';
 65	import { renderChunksToMarkdown } from './chunk-renderer.js';
 66	
 67	// ---------------------------------------------------------------------------
 68	// Path resolution (ESM-safe)
 69	// ---------------------------------------------------------------------------
 70	
 71	const __filename = fileURLToPath(import.meta.url);
 72	const __dirname = dirname(__filename);
 73	
 74	const PUBLIC_DIR = join(__dirname, 'public');
 75	
 76	// ---------------------------------------------------------------------------
 77	// CLI argument parsing
 78	// ---------------------------------------------------------------------------
 79	
 80	function getPort(): number {
 81	  const args = process.argv;
 82	  const idx = args.indexOf('--port');
 83	  if (idx !== -1 && idx + 1 < args.length) {
 84	    const p = parseInt(args[idx + 1]!, 10);
 85	    if (!isNaN(p) && p > 0) return p;
 86	  }
 87	  return 3420;
 88	}
 89	
 90	// ---------------------------------------------------------------------------
 91	// MIME types
 92	// ---------------------------------------------------------------------------
 93	
 94	const MIME_TYPES: Record<string, string> = {
 95	  '.html': 'text/html',
 96	  '.css': 'text/css',
 97	  '.js': 'application/javascript',
 98	};
 99	
100	// ---------------------------------------------------------------------------

101	// CORS helpers
102	// ---------------------------------------------------------------------------
103	
104	function corsHeaders(port: number): Record<string, string> {
105	  return {
106	    'Access-Control-Allow-Origin': `http://localhost:${port}`,
107	    'Access-Control-Allow-Methods': 'GET, POST, PUT, PATCH, DELETE, OPTIONS',
108	    'Access-Control-Allow-Headers': 'Content-Type',
109	  };
110	}
111	
112	// ---------------------------------------------------------------------------
113	// Security headers
114	// ---------------------------------------------------------------------------
115	
116	function securityHeaders(): Record<string, string> {
117	  return {
118	    'X-Content-Type-Options': 'nosniff',
119	    'X-Frame-Options': 'DENY',
120	    'Referrer-Policy': 'strict-origin-when-cross-origin',
121	    'Content-Security-Policy':
122	      "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'",
123	  };
124	}
125	
126	// ---------------------------------------------------------------------------
127	// Response helpers
128	// ---------------------------------------------------------------------------
129	
130	function sendJson(
131	  res: ServerResponse,
132	  status: number,
133	  data: unknown,
134	  port: number
135	): void {
136	  const body = JSON.stringify(data);
137	  res.writeHead(status, {
138	    'Content-Type': 'application/json',
139	    'Content-Length': Buffer.byteLength(body),
140	    ...corsHeaders(port),
141	    ...securityHeaders(),
142	  });
143	  res.end(body);
144	}
145	
146	function sendError(
147	  res: ServerResponse,
148	  status: number,
149	  code: string,
150	  message: string,
151	  port: number
152	): void {
153	  sendJson(res, status, { error: { code, message } }, port);
154	}
155	
156	export function apiErrorToStatus(code: string): number {
157	  switch (code) {
158	    case 'NOT_FOUND':
159	      return 404;
160	    case 'FORBIDDEN':
161	      return 403;
162	    case 'VALIDATION_ERROR':
163	      return 400;
164	    case 'CONFLICT':
165	      return 409;
166	    default:
167	      return 500;
168	  }
169	}
170	
171	// ---------------------------------------------------------------------------
172	// Body reading
173	// ---------------------------------------------------------------------------
174	
175	/** Maximum accepted request body size (1 MiB). */
176	export const MAX_BODY_BYTES = 1_048_576;
177	
178	/** Thrown by {@link readBody} when the request body exceeds {@link MAX_BODY_BYTES}. */
179	export class PayloadTooLargeError extends Error {
180	  constructor() {
181	    super('Payload Too Large');
182	    this.name = 'PayloadTooLargeError';
183	  }
184	}
185	
186	/**
187	 * Reads the full request body as a UTF-8 string, enforcing a size limit of
188	 * {@link MAX_BODY_BYTES} (1 MiB).
189	 *
190	 * @throws {PayloadTooLargeError} When the body exceeds the limit (detected
191	 *   either via Content-Length header pre-check or streaming byte count).
192	 *   **Callers must catch this error and return a 413 response.**
193	 *
194	 * @param req - The incoming HTTP request.
195	 * @returns The full body string.
196	 */
197	function readBody(req: IncomingMessage): Promise<string> {
198	  return new Promise((resolve, reject) => {
199	    // Content-Length pre-check: reject immediately if the declared size exceeds the limit.
200	    const declaredLength = req.headers['content-length'];
201	    if (declaredLength !== undefined) {
202	      const n = parseInt(declaredLength, 10);
203	      if (!isNaN(n) && n > MAX_BODY_BYTES) {
204	        req.resume();  // drain body data from socket buffer
205	        reject(new PayloadTooLargeError());
206	        return;
207	      }
208	    }
209	
210	    const chunks: Buffer[] = [];
211	    let totalBytes = 0;
212	    let rejected = false;
213	
214	    req.on('data', (chunk: Buffer) => {
215	      if (rejected) return;
216	      totalBytes += chunk.length;
217	      if (totalBytes > MAX_BODY_BYTES) {
218	        rejected = true;
219	        reject(new PayloadTooLargeError());
220	        // Drain remaining data so the 413 response can be sent cleanly.
221	        req.resume();
222	        return;
223	      }
224	      chunks.push(chunk);
225	    });
226	    req.on('end', () => {
227	      if (!rejected) resolve(Buffer.concat(chunks).toString('utf-8'));
228	    });
229	    req.on('error', (err) => {
230	      if (!rejected) reject(err);
231	    });
232	  });
233	}
234	
235	/**
236	 * Reads and parses the request body as JSON, enforcing the same size limit as
237	 * {@link readBody}. Throws {@link PayloadTooLargeError} for oversized bodies
238	 * and {@link ApiError} with code `VALIDATION_ERROR` for invalid JSON.
239	 *
240	 * @param req - The incoming HTTP request.
241	 * @returns The parsed JSON value.
242	 */
243	async function readJsonBody(req: IncomingMessage): Promise<unknown> {
244	  const raw = await readBody(req);
245	  try {
246	    return JSON.parse(raw);
247	  } catch {
248	    throw new ApiError('VALIDATION_ERROR', 'Invalid JSON body.');
249	  }
250	}
251	
252	// ---------------------------------------------------------------------------
253	// Router
254	// ---------------------------------------------------------------------------
255	
256	type RouteHandler = () => Promise<unknown>;
257	
258	// ---------------------------------------------------------------------------
259	// Meta helpers
260	// ---------------------------------------------------------------------------
261	
262	/**
263	 * Guards against path-traversal attacks on URL parameters that are used as
264	 * filesystem path segments.
265	 *
266	 * Rejects any segment that is empty or does not match {@link SAFE_SLUG_REGEX}
267	 * (`/^[a-z0-9][a-z0-9-]*$/`). Throws {@link ApiError} `NOT_FOUND` so that
268	 * callers receive the same status as a missing project — no information leak.
269	 *
270	 * @param segment - The raw URL parameter value to validate.
271	 */
272	function assertSafeSlug(segment: string): void {
273	  if (!segment || !SAFE_SLUG_REGEX.test(segment)) {
274	    throw new ApiError('NOT_FOUND', 'Invalid repo or slug parameter.');
275	  }
276	}
277	
278	/**
279	 * Reads the `.meta.json` for a namespaced project at
280	 * `{ledgerRoot}/{repoUrlParam}/{slugUrlParam}/.meta.json`.
281	 *
282	 * Returns the stored `repository_name` value, falling back to `repoUrlParam`
283	 * when the field is absent or null.
284	 *
285	 * When the meta file exists but contains malformed JSON, the function still
286	 * falls back to `repoUrlParam` — but writes a warning to `process.stderr`
287	 * (format: `[server] Warning: malformed .meta.json at {path} — falling back
288	 * to URL param '…'`) so operators can detect corrupt meta files during
289	 * troubleshooting. API callers always receive the fallback value in this case.
290	 *
291	 * Throws {@link ApiError} `NOT_FOUND` when the meta file does not exist —
292	 * indicating that the `{repo}/{slug}` combination is not a known project in
293	 * this ledger. This is the project-existence check for namespaced routes.
294	 * Using `NOT_FOUND` (rather than a 400 or `VALIDATION_ERROR`) is intentional
295	 * information-hiding: invalid-input and missing-project cases are
296	 * indistinguishable from the client side.
297	 *
298	 * Both `repoUrlParam` and `slugUrlParam` are validated via {@link assertSafeSlug}
299	 * before any filesystem access is attempted (defence-in-depth).
300	 */

301	export async function resolveRepoName(
302	  ledgerRoot: string,
303	  repoUrlParam: string,
304	  slugUrlParam: string,
305	): Promise<string> {
306	  assertSafeSlug(repoUrlParam);
307	  assertSafeSlug(slugUrlParam);
308	  const metaPath = join(ledgerRoot, repoUrlParam, slugUrlParam, '.meta.json');
309	  let raw: string;
310	  try {
311	    raw = await readFile(metaPath, 'utf-8');
312	  } catch {
313	    throw new ApiError('NOT_FOUND', `Project not found: ${slugUrlParam}`);
314	  }
315	  try {
316	    const meta = JSON.parse(raw) as { repository_name?: string | null };
317	    return meta.repository_name ?? repoUrlParam;
318	  } catch {
319	    // Malformed .meta.json — project directory exists, fall back to URL param.
320	    // Log to stderr so operators can detect corrupt meta files during troubleshooting.
321	    process.stderr.write(`[server] Warning: malformed .meta.json at ${metaPath} — falling back to URL param '${repoUrlParam}'\n`);
322	    return repoUrlParam;
323	  }
324	}
325	
326	/**
327	 * Matches a method + URL path to an API handler.
328	 * Returns a handler thunk or null if no route matches.
329	 */
330	function matchRoute(
331	  method: string,
332	  url: string,
333	  ledgerRoot: string,
334	  orchestratorLogsDir: string
335	): RouteHandler | null {
336	  const [path] = url.split('?') as [string];
337	  const segments = path.split('/').filter(Boolean);
338	
339	  // All API routes must start with 'api'
340	  if (segments[0] !== 'api') return null;
341	
342	  const rest = segments.slice(1);
343	
344	  // Route dispatch note:
345	  // Routes are matched by segment count (rest.length) first, then by segment values.
346	  // Because the dispatcher walks the if-else chain in declaration order, two routes
347	  // that share the same rest.length value are ordered by their position here — the
348	  // first matching branch wins and subsequent branches at the same length are shadowed.
349	  // When adding a new route with the same rest.length as an existing one (e.g. a future
350	  // /:slug/synthesis at length 3 alongside /:slug/plan), make sure the more-specific
351	  // pattern appears BEFORE the catch-all pattern at that length, or it will never match.
352	
353	  // GET /api/insights
354	  if (method === 'GET' && rest.length === 1 && rest[0] === 'insights') {
355	    return () => handleGetInsights(ledgerRoot);
356	  }
357	
358	  // GET /api/orchestrator/queue
359	  if (method === 'GET' && rest.length === 2 && rest[0] === 'orchestrator' && rest[1] === 'queue') {
360	    return () => handleGetOrchestratorQueue(orchestratorLogsDir, ledgerRoot);
361	  }
362	
363	  // GET /api/orchestrator/run-status/:filename
364	  if (method === 'GET' && rest.length === 3 && rest[0] === 'orchestrator' && rest[1] === 'run-status') {
365	    const filename = decodeURIComponent(rest[2]!);
366	    return () => handleGetRunStatus(orchestratorLogsDir, filename);
367	  }
368	
369	  // GET /api/projects
370	  if (method === 'GET' && rest.length === 1 && rest[0] === 'projects') {
371	    const qIdx = url.indexOf('?');
372	    const qStr = qIdx !== -1 ? url.slice(qIdx + 1) : '';
373	    const sp = new URLSearchParams(qStr);
374	    const params = {
375	      page: sp.get('page') ?? undefined,
376	      limit: sp.get('limit') ?? undefined,
377	      status: sp.get('status') ?? undefined,
378	      search: sp.get('search') ?? undefined,
379	      sort: sp.get('sort') ?? undefined,
380	      dir: sp.get('dir') ?? undefined,
381	      runner: sp.get('runner') ?? undefined,
382	    };
383	    return () => handleListProjects(ledgerRoot, params);
384	  }
385	
386	  // GET /api/projects/:slug/plan
387	  if (
388	    method === 'GET' &&
389	    rest.length === 3 &&
390	    rest[0] === 'projects' &&
391	    rest[2] === 'plan'
392	  ) {
393	    const slug = rest[1]!;
394	    return () => handleGetPlanDocument(ledgerRoot, slug);
395	  }
396	
397	  // GET /api/projects/:slug/synthesis
398	  if (
399	    method === 'GET' &&
400	    rest.length === 3 &&
401	    rest[0] === 'projects' &&
402	    rest[2] === 'synthesis'
403	  ) {
404	    const slug = rest[1]!;
405	    return () => handleGetSynthesisDocument(ledgerRoot, slug);
406	  }
407	
408	  // GET /api/projects/:slug/health
409	  if (
410	    method === 'GET' &&
411	    rest.length === 3 &&
412	    rest[0] === 'projects' &&
413	    rest[2] === 'health'
414	  ) {
415	    const slug = rest[1]!;
416	    return () => handleGetProjectHealth(ledgerRoot, slug);
417	  }
418	
419	  // GET /api/projects/:slug
420	  if (method === 'GET' && rest.length === 2 && rest[0] === 'projects') {
421	    const slug = rest[1]!;
422	    return () => handleGetProject(ledgerRoot, slug);
423	  }
424	
425	  // GET /api/projects/:slug/work-packages
426	  if (
427	    method === 'GET' &&
428	    rest.length === 3 &&
429	    rest[0] === 'projects' &&
430	    rest[2] === 'work-packages'
431	  ) {
432	    const slug = rest[1]!;
433	    return () => handleListWorkPackages(ledgerRoot, slug);
434	  }
435	
436	  // GET /api/projects/:slug/work-packages/overview
437	  // IMPORTANT: this route has rest.length === 4 and must appear BEFORE the
438	  // generic /:wpId handler at the same length, otherwise 'overview' would be
439	  // treated as a WP ID.
440	  if (
441	    method === 'GET' &&
442	    rest.length === 4 &&
443	    rest[0] === 'projects' &&
444	    rest[2] === 'work-packages' &&
445	    rest[3] === 'overview'
446	  ) {
447	    const slug = rest[1]!;
448	    return () => handleGetWorkPackageOverview(ledgerRoot, slug);
449	  }
450	
451	  // GET /api/projects/:slug/dialogues/:filename
452	  // rest.length === 4, rest[2] === 'dialogues' — must appear before the generic
453	  // work-packages/:wpId handler at the same length.
454	  if (
455	    method === 'GET' &&
456	    rest.length === 4 &&
457	    rest[0] === 'projects' &&
458	    rest[2] === 'dialogues'
459	  ) {
460	    const slug = rest[1]!;
461	    const filename = decodeURIComponent(rest[3]!);
462	    return () => handleGetDialogueFile(ledgerRoot, slug, filename);
463	  }
464	
465	  // GET /api/projects/:slug/work-packages/:wpId
466	  if (
467	    method === 'GET' &&
468	    rest.length === 4 &&
469	    rest[0] === 'projects' &&
470	    rest[2] === 'work-packages'
471	  ) {
472	    const slug = rest[1]!;
473	    const wpId = rest[3]!;
474	    return () => handleGetWorkPackage(ledgerRoot, slug, wpId);
475	  }
476	
477	  // GET /api/projects/:slug/dialogues[?wp=WP-001]
478	  // rest.length === 3, rest[2] === 'dialogues' — does not shadow other rest[2] routes
479	  if (
480	    method === 'GET' &&
481	    rest.length === 3 &&
482	    rest[0] === 'projects' &&
483	    rest[2] === 'dialogues'
484	  ) {
485	    const slug = rest[1]!;
486	    const qIdx = url.indexOf('?');
487	    const qStr = qIdx !== -1 ? url.slice(qIdx + 1) : '';
488	    const sp = new URLSearchParams(qStr);
489	    const wpId = sp.get('wp') ?? undefined;
490	    return () => handleListDialogues(ledgerRoot, slug, wpId);
491	  }
492	
493	  // GET /api/projects/:slug/chunks
494	  // rest.length === 3, rest[2] === 'chunks' — analogous to the dialogues list route
495	  if (
496	    method === 'GET' &&
497	    rest.length === 3 &&
498	    rest[0] === 'projects' &&
499	    rest[2] === 'chunks'
500	  ) {
501	    const slug = rest[1]!;
502	    const qIdx = url.indexOf('?');
503	    const qStr = qIdx !== -1 ? url.slice(qIdx + 1) : '';
504	    const sp = new URLSearchParams(qStr);
505	    const wpId = sp.get('wp') ?? undefined;
506	    return () => handleListChunks(ledgerRoot, slug, wpId);
507	  }
508	
509	  // GET /api/projects/:slug/chunks/:filename/rendered
510	  // rest.length === 5, rest[2] === 'chunks', rest[4] === 'rendered'
511	  // Placement note: this route (rest.length === 5) and the raw-file route below
512	  // (rest.length === 4) have different segment counts, so there is no ordering
513	  // requirement between them — the dispatcher can never confuse the two.  This
514	  // block is placed here (before the length-4 route) solely to keep all three
515	  // chunk routes visually adjacent and in URL-specificity order.
516	  if (
517	    method === 'GET' &&
518	    rest.length === 5 &&
519	    rest[0] === 'projects' &&
520	    rest[2] === 'chunks' &&
521	    rest[4] === 'rendered'
522	  ) {
523	    const slug = rest[1]!;
524	    const filename = decodeURIComponent(rest[3]!);
525	    return () =>
526	      handleGetChunkFile(ledgerRoot, slug, filename).then(({ content }) => ({
527	        content: renderChunksToMarkdown(content),
528	      }));
529	  }
530	
531	  // GET /api/projects/:slug/chunks/:filename
532	  // rest.length === 4, rest[2] === 'chunks' — analogous to dialogues/:filename
533	  if (
534	    method === 'GET' &&
535	    rest.length === 4 &&
536	    rest[0] === 'projects' &&
537	    rest[2] === 'chunks'
538	  ) {
539	    const slug = rest[1]!;
540	    const filename = decodeURIComponent(rest[3]!);
541	    return () => handleGetChunkFile(ledgerRoot, slug, filename);
542	  }
543	
544	  // ---------------------------------------------------------------------------
545	  // Namespaced /:repo/:slug routes — added in WP-009.
546	  // Each route validates repo and slug separately via SAFE_SLUG_REGEX (same
547	  // enforcement as assertSafeSlug but applied before any handler call, giving
548	  // explicit path-traversal defence at the routing layer).
549	  // resolveRepoName() reads .meta.json to obtain the canonical repository_name
550	  // and also serves as the project-existence check (throws NOT_FOUND when the
551	  // meta file is absent).
552	  //
553	  // Ordering note: all keyword-specific /:slug/xxx routes at rest.length===3
554	  // appear ABOVE the /:repo/:slug catch-all at the same length. The catch-all
555	  // uses explicit keyword exclusion to prevent shadowing.
556	  // ---------------------------------------------------------------------------
557	
558	  // GET /api/projects/:repo/:slug/plan
559	  // rest.length === 4, rest[3] === 'plan' — does not conflict with /:slug/keyword (length 3)
560	  if (
561	    method === 'GET' &&
562	    rest.length === 4 &&
563	    rest[0] === 'projects' &&
564	    rest[3] === 'plan' &&
565	    rest[2] !== 'plan' &&
566	    rest[2] !== 'synthesis' &&
567	    rest[2] !== 'health' &&
568	    rest[2] !== 'work-packages' &&
569	    rest[2] !== 'dialogues' &&
570	    rest[2] !== 'chunks' &&
571	    rest[2] !== 'runs'
572	  ) {
573	    const repoUrlParam = decodeURIComponent(rest[1]!);
574	    const slug = decodeURIComponent(rest[2]!);
575	    return async () => {
576	      if (!SAFE_SLUG_REGEX.test(repoUrlParam) || !SAFE_SLUG_REGEX.test(slug)) {
577	        throw new ApiError('NOT_FOUND', 'Invalid repo or slug parameter.');
578	      }
579	      const repoName = await resolveRepoName(ledgerRoot, repoUrlParam, slug);
580	      return handleGetPlanDocument(ledgerRoot, slug, repoName);
581	    };
582	  }
583	
584	  // GET /api/projects/:repo/:slug/synthesis
